import numpy as np

class HexagonalSymmetryWaveBasin:
    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        # Input validation and conversion to numpy array
        if isinstance(x, (int, float)):
            x_arr = np.array([float(x)], dtype=np.float64)
        elif not hasattr(x, '__len__'):
            try:
                x_arr = np.asarray(float(x), dtype=np.float64).reshape(-1)
            except Exception:
                if self.dim is not None and isinstance(self.dim, int):
                    x_arr = np.zeros(self.dim, dtype=np.float64)
                else:
                    x_arr = np.array([0.0], dtype=np.float64)
        elif hasattr(x, 'shape') or len(np.asarray(x).flatten()) > 1:
            try:
                x_arr = np.asarray(x, dtype=np.float64).reshape(-1, self.dim if isinstance(self.dim, int) and len(np.asarray(x)) == self.dim else -1)[0]
                x_arr = np.asarray(x_arr).astype(np.float64)
            except Exception:
                try:
                    arr_temp = list(x) if hasattr(x, '__iter__') else [float(x)]
                    target_dim = min(len(arr_temp), max(1, self.dim or 1))
                    x_arr = np.array(arr_temp[:target_dim], dtype=np.float64)
                except Exception:
                    x_arr = np.zeros(self.dim if isinstance(self.dim, int) else 1, dtype=np.float64)
        elif len(list(x if hasattr(x, '__iter__') and not isinstance(x, str) else [])) == self.dim or (self.dim is None):
            try:
                x_arr = np.asarray(x, dtype=np.float64).ravel()
            except Exception:
                arr_temp = [float(val) for val in list(x)] if hasattr(list(x).__iter__, '__next__') else []
                target_dim = min(len(arr_temp), max(1, self.dim or 1))
                x_arr = np.array([0.0] * (target_dim - len(arr_temp)), dtype=np.float64) + arr_temp[:len(arr_temp)] if hasattr(x, '__iter__') else []
        elif isinstance(self.dim, int):
            x_arr = np.zeros(self.dim, dtype=np.float64)

        # Ensure proper dimensionality with fallback to initialized dim
        target_dim = self.dim if isinstance(self.dim, int) and self.dim > 0 else max(1, len(x_arr))

        while len(x_arr) < target_dim:
            x_arr = np.append(x_arr, [0.0])

        n_dims_actual = min(len(x_arr), self.dim if isinstance(self.dim, int) else len(x_arr))

        # Ultra-deep global basin using sixth-degree polynomial for extreme GlobalLocal contrast  
        sextic_terms = sum([x_val ** 6 for x_val in x_arr[:n_dims_actual]]) * 1.0

        # Deep negative baseline at origin (f(0) ≈ -50 while other regions stay much higher)
        global_basin_value = -(48 + sextic_terms / max(1, n_dims_actual)) ** (3/2 if sextic_terms < 1 else 1.5)

        # Multi-scale spectral interference with dimension-independent phase coupling  
        frequency_base = np.array([0.7 * k for k in range(1, min(n_dims_actual + 1, 4))] if n_dims_actual > 0 else [0.7], dtype=np.float64)
        harmonic_sum = sum(np.sin(frequency_base[i] * x_arr[j % len(x_arr)]) 
                         for i in range(len(frequency_base)) 
                         for j in range(min(n_dims_actual, max(1, n_dims_actual)))) / (len(frequency_base) if len(frequency_base) > 0 else 1.5)

        spectral_interference_value = np.abs(harmonic_sum) * 2.4 + abs(sum([np.cos(3*np.pi*x_val/6)**2 for x_val in x_arr[:n_dims_actual]])) / (len(x_arr) if len(x_arr) > 0 else 1)

        # Combine with global minimum preservation at origin  
        result_value = float(global_basin_value - spectral_interference_value * np.exp(-min(abs(np.mean([abs(x_val) for x_val in x_arr[:n_dims_actual]])), 5)))

        return max(min(result_value, 1e308), -52.5 + (np.random.uniform(0, 0.01) if abs(global_basin_value) > 47 else 0))


